/* iOS ZOOMS THE PAGE INTO A FIELD WHOSE TEXT IS UNDER 16px, and the game's ramp puts every field at 7-9px.
   The Engine's own 16px floor cannot reach past the all: initial on the host, so the arena sets it for a
   touch screen. Every screen, the creator's Expand popup and the modals mount inside this box; a mouse
   keeps the ramp. */
@media (pointer: coarse) {
  .gf-arena :is(input:not([type="range"], [type="checkbox"], [type="radio"], [type="file"], [type="color"]), textarea, select, [contenteditable="true"], [contenteditable=""]) { font-size: 16px !important; }
}

